select pg_temp.expect_error($q$select public.save_customer_design('89000000-0000-4000-8000-000000000001','{"name":"Canvas annotations","garment_type":"shirt","colour":"navy","neckline":"round","sleeve":"long","length":"midi","format_version":3,"garment_options":{"collar":"point"},"decorations":{"version":1,"strokes":[{"colour":"#303039","width":3,"points":[[100,100],[9000,9000]],"mode":null}]}}'::jsonb,1)$q$,'22023');
select pg_temp.expect_error($q$select public.save_customer_design('89000000-0000-4000-8000-000000000001','{"name":"Canvas annotations","garment_type":"shirt","colour":"navy","neckline":"round","sleeve":"long","length":"midi","format_version":3,"garment_options":{"collar":"point"},"decorations":{"version":1,"strokes":[{"colour":"#303039","width":3,"points":[[100,100],[9000,9000]],"mode":1}]}}'::jsonb,1)$q$,'22023');
select pg_temp.expect_error($q$select public.save_customer_design('89000000-0000-4000-8000-000000000001','{"name":"Canvas annotations","garment_type":"shirt","colour":"navy","neckline":"round","sleeve":"long","length":"midi","format_version":3,"garment_options":{"collar":"point"},"decorations":{"version":1,"strokes":[{"colour":"#303039","width":3,"points":[[100,100],[9000,9000]],"mode":"svg"}]}}'::jsonb,1)$q$,'22023');
select pg_temp.expect_error($q$select public.save_customer_design('89000000-0000-4000-8000-000000000001','{"name":"Canvas annotations","garment_type":"shirt","colour":"navy","neckline":"round","sleeve":"long","length":"midi","format_version":3,"garment_options":{"collar":"point"},"decorations":{"version":1,"strokes":[{"colour":"#303039","width":3,"points":[[100,100],[9000,9000]],"mode":""}]}}'::jsonb,1)$q$,'22023');
select pg_temp.expect_error($q$select public.save_customer_design('89000000-0000-4000-8000-000000000001','{"name":"Canvas annotations","garment_type":"shirt","colour":"navy","neckline":"round","sleeve":"long","length":"midi","format_version":3,"garment_options":{"collar":"point"},"decorations":{"version":1,"strokes":[{"colour":"#303039","width":3,"points":[[100,100],[9000,9000]],"mode":{}}]}}'::jsonb,1)$q$,'22023');
select public.send_tailoring_request_with_design('89000000-0000-4000-8000-000000000002','50000000-0000-4000-8000-000000000002','shirt','Please include these canvas annotations.',1,current_date+30,'89000000-0000-4000-8000-000000000001',1);
reset role;
update public.customer_designs set decorations='{"version":1,"strokes":[]}' where id='89000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select decorations='{"version":1,"strokes":[{"colour":"#303039","width":3,"points":[[100,100],[9000,9000]]},{"colour":"#303039","width":3,"points":[[100,100],[9000,9000]],"mode":"canvas"},{"colour":"#303039","width":3,"points":[[100,100],[9000,9000]],"mode":"garment"}]}'::jsonb from public.request_design_snapshots where request_id='89000000-0000-4000-8000-000000000002'),'tailor receives immutable canvas and clipped annotations');
reset role;
select pg_temp.assert_true((select decorations='{"version":1,"strokes":[{"colour":"#303039","width":3,"points":[[100,100],[9000,9000]]}]}' from public.customer_designs where id='84000000-0000-4000-8000-000000000001'),'pre-migration clipped source unchanged');
select pg_temp.assert_true((select decorations='{"version":1,"strokes":[{"colour":"#303039","width":3,"points":[[100,100],[9000,9000]]}]}' from public.request_design_snapshots where design_id='84000000-0000-4000-8000-000000000001'),'pre-migration clipped snapshot unchanged');
rollback;
select 'PASS: drawing placement modes, drawing limits, save/reopen, ownership, immutable combined snapshots and legacy preservation' as result;
